import { _decorator, Component, Node} from 'cc';
import { Entity } from './Engine/Entity';
import { System } from './Engine/System';
import { Bus } from './Engine/Bus';
import { World } from './Engine/World';
const { ccclass, property } = _decorator;

class TestEntity extends Entity{
    readonly kind = 'test';
    public vx = 10;
    public name = '';
}

class moveSystem  implements System{
    onStart(world: World): void{
        console.log("start");
    }

    onTick(world: World, dt :number): void{
        let count = 0;
        for(const e of world.query<TestEntity>('test')){
            e.x += e.vx * dt;
            count++;
        }
        if (count > 0) {
            console.log(`[MovementSystem] tick, 处理了 ${count} 个实体, dt=${dt.toFixed(4)}`);
        }
    }
}

// ========== System 2：检查谁跑远了 ==========
class CullSystem implements System {
    onTick(world: World, dt: number): void {
        for (const e of world.query<TestEntity>('test')) {
            if (e.x > 100) {
                console.log(`[CullSystem] ${e.name} 跑远了(x=${e.x.toFixed(1)})，移除`);
                world.remove(e);
            }
        }
    }
}

@ccclass('TestRunner')
export class TestRunner extends Component {
    start() {
      // 1. 组装 World
        const bus = new Bus();
        this._world = new World(bus);
        this._world.addSystem(new MovementSystem());
        this._world.addSystem(new CullSystem());

        // 2. 放 3 个 Entity
        for (let i = 0; i < 3; i++) {
            const e = new TestEntity();
            e.name = `e${i}`;
            e.x = 0;
            this._world.add(e);
            console.log(`创建 ${e.name}, id=${e.id}`);
        }

    }


}


